# Look at HARD_LIMIT_REACHED frequency over time for reviewer
cat /home/ubuntu/.agent-ml-research-idea_gen_0519/projects/nlp_variance_gtheory/logs/ralph_loop_timeline.jsonl | python3 -c "
import json, sys
events = []
for line in sys.stdin:
    if line.strip():
        try:
            events.append(json.loads(line))
        except: pass
# By role and event type
print('Reviewer HARD_LIMIT_REACHED times:')
for e in events:
    if e.get('event') == 'HARD_LIMIT_REACHED' and e.get('role') == 'reviewer':
        print(f'  {e.get(\"ts\",\"?\")[:19]}')
print()
print('All ESCALATED_SILENT:')
for e in events:
    if e.get('event') == 'ESCALATED_SILENT':
        print(f'  ts={e.get(\"ts\",\"?\")[:19]} role={e.get(\"role\")} data={e.get(\"data\")}')
"

# Sample beginning of director session and look for human intervention markers
sed -n '1,5p' /home/ubuntu/.claude-account-2/projects/-home-ubuntu--agent-ml-research-idea-gen-0519-projects-nlp-variance-gtheory--claude-sessions-director-754d9c1f/a4c29143-4270-4e07-aa5b-b943dedfe43e.jsonl | python3 -c "
import json, sys
for i, line in enumerate(sys.stdin):
    try:
        d = json.loads(line)
        print(f'--- entry {i} ---')
        print('type:', d.get('type'))
        if 'message' in d:
            msg = d['message']
            if isinstance(msg, dict):
                role = msg.get('role','?')
                content = msg.get('content','')
                if isinstance(content, str):
                    print(f'role={role} content[:500]={content[:500]}')
                elif isinstance(content, list):
                    for c in content[:2]:
                        if isinstance(c, dict):
                            t = c.get('type','?')
                            if t == 'text':
                                print(f'role={role} text[:500]={str(c.get(\"text\",\"\"))[:500]}')
                            else:
                                print(f'role={role} {t}: {str(c)[:300]}')
    except Exception as e:
        print(f'err: {e}')
"
